<template>
<main class="medical-page simulation-preparation">
<h1>模拟准备</h1><session-panel/>
<el-alert type="warning" :closable="false" title="仅用于模拟评测，无生产资格。目录可见、配置声明和上传完成都不代表已获模拟许可。"/>
<p>案例与输入须为包含合法 SimulationCase / ExactInput JSON 的 UTF-8 TXT 原件，经过实际上传和来源核准。当前权利须允许 SIMULATION_EVALUATION、READ、ENTERPRISE_USE。登记不创建许可或执行模型。</p>
<simulation-feature-availability feature="input_artifact_registration" @change="inputEnabled=$event">
<p v-if="error" role="alert">{{ error }}</p>
<section v-if="pending" class="card"><h2>保留的原登记请求</h2><p>{{ pending.stage === 'FIXTURE' ? '案例登记' : '输入制品登记' }} · {{ pending.key }}{{ pending.stage==='FIXTURE'?'（本地恢复标识，服务器未使用幂等key）':'' }}</p><p>未知结果不能视为失败。保留完整原参数，不能换请求覆盖。案例登记没有操作查询接口；跨上下文只能查询输入制品原请求。</p><pre>{{ JSON.stringify(pending.request,null,2) }}</pre>
<el-checkbox v-model="confirmed" :disabled="busy">我已核查完整原参数，确认执行下方操作</el-checkbox>
<el-button v-if="pending.stage==='INPUT'" :disabled="busy" @click="lookup">查询原输入登记</el-button>
<el-button :disabled="busy || !confirmed || !sameContext" @click="sendPending">按原参数显式{{ pending.stage==='INPUT'?'重放输入登记':'复核并重放案例登记' }}</el-button>
<p v-if="lookupStatus">{{ lookupStatus==='NOT_FOUND'?'当前未找到记录，不能判定原请求未发生；不会自动重试。':'已读取原登记回执。' }}</p><p v-if="!sameContext">上下文已变化，禁止重放原写入。</p></section>
<template v-else>
<section class="card"><h2>1. 选择固定模型配置</h2><el-button :disabled="busy" @click="loadModels()">读取模拟模型目录</el-button><el-button v-if="models?.next_after" :disabled="busy" @click="loadModels(models.next_after)">下一页</el-button>
<el-select v-model="modelId" :disabled="busy || !!fixture" placeholder="选择真实配置修订" @change="chooseModel"><el-option v-for="item in models?.items ?? []" :key="item.model_config_revision" :value="item.model_config_revision" :label="item.definition.model_id+' · '+item.model_config_revision"/></el-select>
<p v-if="model">配置 {{ model.model_config_revision }}；范围 {{ model.project_id ?? '企业' }}；声明案例 {{ model.definition.case_binding.case_id }}（尚不证明登记成功）</p></section>
<section v-if="model" class="card"><h2>2. 选择案例与输入原件</h2><el-button :disabled="busy || !!fixture" @click="loadSources()">读取已核准来源目录</el-button><el-button v-if="sources?.next_after" :disabled="busy || !!fixture" @click="loadSources(sources.next_after)">下一页来源</el-button>
<div class="grid"><el-form-item label="案例原件"><el-select v-model="caseId" :disabled="busy || !!fixture" @change="chooseSource('case')"><el-option v-for="item in sourceOptions" :key="item.source_version" :value="item.source_version" :label="item.title+' · '+item.source_version"/></el-select></el-form-item><el-form-item label="输入原件"><el-select v-model="inputId" :disabled="busy || !!fixture" @change="chooseSource('input')"><el-option v-for="item in sourceOptions" :key="item.source_version" :value="item.source_version" :label="item.title+' · '+item.source_version"/></el-select></el-form-item></div>
<p v-for="item in [caseSource,inputSource].filter(Boolean)" :key="item!.source_version">{{ item!.title }} · {{ item!.source_version }} · 权利 {{ item!.rights_revision }} / {{ item!.rights_status }} / {{ item!.rights_purpose }} · 原件SHA {{ item!.original_sha256 }}</p></section>
<section v-if="model" class="card"><h2>3. 核查真实请求参数</h2><div class="grid"><el-form-item label="最大输出 Token"><el-input v-model="maximum" :disabled="busy || !!fixture"/></el-form-item><el-form-item label="temperature（留空表示 null）"><el-input v-model="temperature" :disabled="busy || !!fixture"/></el-form-item><el-form-item label="reasoning_effort（留空表示 null）"><el-select v-model="effort" clearable :disabled="busy || !!fixture"><el-option v-for="value in model.definition.limits.reasoning_efforts" :key="value" :value="value" :label="value"/></el-select></el-form-item><el-form-item label="停止词，每行一项；空文本表示空数组"><el-input v-model="stops" type="textarea" :disabled="busy || !!fixture"/></el-form-item></div><p>协议目的：EVALUATION。必须与原案例声明的参数摘要一致，没有自动默认参数。</p>
<el-checkbox v-model="confirmed" :disabled="busy">我已核查固定版本、来源与参数，明确登记</el-checkbox><el-button v-if="!fixture" :disabled="busy || !confirmed" @click="prepareFixture">登记案例 fixture</el-button></section>
<section v-if="fixture" class="card"><h2>案例登记回执</h2><p>案例 {{ fixture.case_id }} · 回执 {{ fixture.case_receipt_id }}</p><p>canonical 案例 SHA：{{ fixture.case_sha256 }}</p><p>canonical 输入 SHA：{{ fixture.input_sha256 }}（不能用作输入制品 raw SHA）</p><el-button :disabled="busy || !confirmed || !!artifact" @click="prepareInput">明确登记输入 ARTIFACT</el-button></section>
</template>
<section v-if="artifact" class="card"><h2>输入制品真实回执</h2><p>SIMULATION · production_eligible=false</p><p>ARTIFACT：{{ artifact.input_ref.version_id }}</p><p>原字节 raw SHA：{{ artifact.input_ref.content_sha256 }}</p><pre>{{ JSON.stringify(artifact.source_binding,null,2) }}</pre><el-input type="textarea" readonly :model-value="JSON.stringify(artifact.input_ref)" aria-label="可复制的输入固定引用"/><p>可选择复制以上真实引用；登记不代表完整评测定义已准备或评测已运行。</p></section>
</simulation-feature-availability>
<simulation-feature-availability feature="evaluation_preparation"><simulation-evaluation-preparation :input-ref="artifact?.input_ref"/></simulation-feature-availability>
</main>
</template>
<script setup lang="ts">
import { computed, ref, watch, onBeforeUnmount } from 'vue'
import useUserStore from '@/store/modules/user'
import SessionPanel from './session-panel.vue'
import SimulationEvaluationPreparation from './simulation-evaluation-preparation.vue'
import SimulationFeatureAvailability from './simulation-feature-availability.vue'
import { listSimulationConfigurations, readSimulationConfiguration } from '@/api/medical/simulation-model-configurations'
import type { SimulationListing, SimulationView } from '@/api/medical/simulation-model-configuration-domain'
import { readSourceCatalogue, readSourceGovernance } from '@/api/medical/source-governance'
import type { SourceCataloguePage, SourceGovernanceView } from '@/api/medical/source-governance'
import { registerFixture, registerInputArtifact, lookupInputArtifact } from '@/api/medical/simulation-fixtures'
import { fixtureIssues, canonicalFixture, preparationDigest, readPreparation, savePreparation, clearPreparation, verifyPending, preparationAllowed } from '@/api/medical/simulation-fixture-domain'
import type { FixtureRequest, FixtureReceipt, InputReceipt, PendingPreparation } from '@/api/medical/simulation-fixture-domain'
const inputEnabled=ref(false)
const user=useUserStore(), models=ref<SimulationListing|null>(null),model=ref<SimulationView|null>(null),sources=ref<SourceCataloguePage|null>(null)
const modelId=ref(''),caseId=ref(''),inputId=ref(''),caseSource=ref<SourceGovernanceView|null>(null),inputSource=ref<SourceGovernanceView|null>(null)
const maximum=ref(''),temperature=ref(''),effort=ref(''),stops=ref(''),confirmed=ref(false),error=ref(''),loading=ref(false)
const fixture=ref<FixtureReceipt|null>(null),artifact=ref<InputReceipt|null>(null),pending=ref<PendingPreparation|null>(null),completed=ref<PendingPreparation|null>(null),lookupStatus=ref('')
const busy=computed(()=>loading.value||user.medicalWriting),sameContext=computed(()=>!!pending.value && canonicalFixture(pending.value.context)===canonicalFixture(user.medicalSession?.current_context))
const sourceOptions=computed(()=>sources.value?.items.filter(i=>i.ownership!=='SESSION')??[])
let generation=0,controller=new AbortController(),active=true,owned=false
function current(g:number,s:unknown){return active&&g===generation&&s===user.medicalSession&&!document.hidden}
async function read<T>(work:(s:NonNullable<typeof user.medicalSession>,signal:AbortSignal)=>Promise<T>,apply:(v:T)=>void){const s=user.medicalSession;if(!inputEnabled.value||!s?.current_context||busy.value||document.hidden)return;const g=generation;loading.value=true;error.value='';try{const v=await work(s,controller.signal);if(current(g,s))apply(v)}catch(e){if(current(g,s))error.value=e instanceof Error?e.message:'读取失败'}finally{if(current(g,s))loading.value=false}}
function loadModels(after?:string){return read((s,signal)=>listSimulationConfigurations(s,{limit:20,...(after?{after}:{})},signal),v=>{models.value=v})}
function chooseModel(){fixture.value=null;artifact.value=null;caseSource.value=null;inputSource.value=null;caseId.value='';inputId.value='';sources.value=null;confirmed.value=false;model.value=null;const id=modelId.value;return read((s,signal)=>readSimulationConfiguration(s,id,signal),v=>{if(id===modelId.value)model.value=v})}
function loadSources(after?:string){return read((s,signal)=>readSourceCatalogue(s,{limit:25,approval_status:'APPROVED',lifecycle:'ACTIVE',...(model.value?.project_id?{project_id:model.value.project_id}:{}),...(after?{after}:{})},signal),v=>{sources.value=v})}
function chooseSource(kind:'case'|'input'){const id=kind==='case'?caseId.value:inputId.value;if(kind==='case')caseSource.value=null;else inputSource.value=null;confirmed.value=false;return read((s,signal)=>readSourceGovernance(s,id,signal),v=>{if(kind==='case'&&id===caseId.value)caseSource.value=v;else if(kind==='input'&&id===inputId.value)inputSource.value=v})}
function localRequest():FixtureRequest|null{if(!model.value||!caseSource.value||!inputSource.value){error.value='请读取模型及两份固定来源';return null}if(!/^[1-9][0-9]*$/.test(maximum.value)||!Number.isSafeInteger(Number(maximum.value))||temperature.value!==''&&(!Number.isFinite(Number(temperature.value))||temperature.value.trim()!==temperature.value)){error.value='请填写有效Token整数与温度数值';return null}
 const p={max_output_tokens:Number(maximum.value),temperature:temperature.value===''?null:Number(temperature.value),reasoning_effort:effort.value||null,stop:stops.value===''?[]:stops.value.split('\n'),purpose:'EVALUATION' as const}
 const body:FixtureRequest={schema_version:'1.0.0',project_id:model.value.project_id,model_config_revision:model.value.model_config_revision,case_source_version:caseSource.value.source_version,case_rights_revision:caseSource.value.rights_revision,input_source_version:inputSource.value.source_version,input_rights_revision:inputSource.value.rights_revision,request_parameters:p}
 if(new TextEncoder().encode(JSON.stringify(body)).length>65536||fixtureIssues(body).length||BigInt(maximum.value)>BigInt(model.value.definition.limits.max_output_tokens)||p.stop.length>model.value.definition.limits.stop_limit||p.temperature!==null&&(!model.value.definition.limits.temperature_enabled||p.reasoning_effort!=='none'||p.temperature<0||p.temperature>2)){error.value='参数不符合固定配置或登记格式';return null}return body}
async function prepareFixture(){if(!inputEnabled.value||busy.value||pending.value||!confirmed.value)return;const request=localRequest(),s=user.medicalSession;if(!request||!s?.current_context)return;if(!preparationAllowed(s,'model.configure')){error.value='当前没有模型配置维护权限';return}const g=generation;loading.value=true;try{const p={actor:s.user.user_id,context:{...s.current_context},stage:'FIXTURE' as const,key:crypto.randomUUID(),request,case_id:model.value!.definition.case_binding.case_id,case_hash:model.value!.definition.case_binding.case_sha256,input_source_id:inputSource.value!.source_id,raw_hash:inputSource.value!.original_sha256};const digest=await preparationDigest(p);if(!current(g,s))return;pending.value={...p,digest};savePreparation(s,pending.value)}finally{if(current(g,s))loading.value=false}await sendPending()}
async function prepareInput(){if(!inputEnabled.value||busy.value||pending.value||!confirmed.value||!completed.value||!fixture.value)return;const s=user.medicalSession;if(!s?.current_context)return;if(!preparationAllowed(s,'artifact.register')){error.value='当前没有输入制品登记权限';return}const g=generation;loading.value=true;try{const p={...completed.value,stage:'INPUT' as const,key:crypto.randomUUID()};p.digest=await preparationDigest(p);if(!current(g,s))return;pending.value=p;savePreparation(s,p)}finally{if(current(g,s))loading.value=false}await sendPending()}
async function sendPending(){const s=user.medicalSession,p=pending.value;if(!inputEnabled.value||!s?.current_context||!p||busy.value||!confirmed.value||!sameContext.value||document.hidden)return;const g=generation;owned=true;user.medicalWriting=true;error.value='';try{if(p.stage==='FIXTURE'){const r=await registerFixture(s,p,controller.signal);if(current(g,s)){fixture.value=r;completed.value=p;pending.value=null;clearPreparation(s);confirmed.value=false}}else{const r=await registerInputArtifact(s,p,controller.signal);if(current(g,s)){artifact.value=r;completed.value=p;pending.value=null;clearPreparation(s);confirmed.value=false}}}catch(e){if(current(g,s))error.value=e instanceof Error?e.message:'结果未知，请保留原请求核查'}finally{if(owned){owned=false;user.medicalWriting=false}}}
function lookup(){const p=pending.value;if(!p||p.stage!=='INPUT')return;return read((s,signal)=>lookupInputArtifact(s,p,signal),v=>{lookupStatus.value=v.status;if(v.receipt)artifact.value=v.receipt})}
function reset(){generation++;controller.abort();controller=new AbortController();models.value=null;model.value=null;sources.value=null;modelId.value='';caseId.value='';inputId.value='';caseSource.value=null;inputSource.value=null;maximum.value='';temperature.value='';effort.value='';stops.value='';confirmed.value=false;error.value='';fixture.value=null;artifact.value=null;pending.value=null;completed.value=null;lookupStatus.value='';loading.value=false}
async function restore(){reset();const s=user.medicalSession;if(!inputEnabled.value||!s?.current_context||document.hidden)return;const g=generation;try{const p=readPreparation(s);if(p){await verifyPending(s,p,false);if(current(g,s))pending.value=p}}catch(e){if(current(g,s))error.value=e instanceof Error?e.message:'恢复失败'}}
watch(inputEnabled,()=>{void restore()},{flush:'sync'})
watch(()=>[user.medicalSession,canonicalFixture(user.medicalSession?.current_context ?? null)],restore,{immediate:true,flush:'sync'});watch([maximum,temperature,effort,stops],()=>{confirmed.value=false},{flush:'sync'})
function visibility(){void restore()}function leaving(e:BeforeUnloadEvent){if(pending.value||owned){e.preventDefault();e.returnValue=''}}
document.addEventListener('visibilitychange',visibility);window.addEventListener('beforeunload',leaving)
onBeforeUnmount(()=>{active=false;reset();document.removeEventListener('visibilitychange',visibility);window.removeEventListener('beforeunload',leaving)})
</script>
<style scoped>.simulation-preparation{padding:24px;max-width:1200px;margin:auto}.card{padding:20px;border:1px solid #dce3ec;background:white;border-radius:8px;margin:20px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}p,pre{overflow-wrap:anywhere;white-space:pre-wrap}.el-select{width:100%;margin:10px 0}.el-button{margin:8px} @media(max-width:700px){.grid{grid-template-columns:1fr}}</style>
